cat > test/labels.test.ts <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import type { BranchResource } from "../src/filter.ts";
import { branchOf, byBranch, isUntagged, matches } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";
import { summarize } from "../src/report.ts";

function resource(id: string, fields: Partial<BranchResource> = {}): BranchResource {
  return {
    id, type: "instance", name: id, tags: {}, stack_id: null,
    depends_on: [], cost_month_cents: 100, created_at: "2024-11-01T00:00:00Z",
    ...fields,
  };
}

test("branch labels ignore key casing, but branch values remain exact", () => {
  for (const key of ["Branch", "branch", "BRANCH", "bRaNcH"]) {
    const r = resource(key, { labels: { [key]: "feat-a", Team: "payments" } });
    assert.equal(branchOf(r), "feat-a");
    assert.equal(isUntagged(r), false);
    assert.ok(matches(r, [["branch", "feat-a"], ["team", "payments"]]));
    assert.equal(buildPlan([r], "FEAT-A").steps.length, 0);
    assert.equal(buildPlan([r], "feat-a").steps.length, 1);
  }
  assert.equal(branchOf(resource("none")), undefined);
  assert.equal(branchOf(resource("other-label", { labels: { Team: "payments" } })), undefined);
  assert.equal(branchOf(resource("conflict", {
    tags: { branch: "feat-b" }, labels: { Branch: "feat-a" },
  })), "feat-b");
});

test("label-only resources are grouped and reported as branch-owned, not GC candidates", () => {
  const resources = [
    resource("labelled", { labels: { Branch: "feat-a" } }),
    resource("tagged", { tags: { branch: "feat-a" } }),
    resource("orphan"),
  ];
  assert.equal(byBranch(resources).get("feat-a")?.length, 2);
  assert.deepEqual(resources.filter(isUntagged).map((r) => r.id), ["orphan"]);
  assert.match(summarize(resources), /feat-a\s+2/);
  assert.match(summarize(resources), /1 untagged resources/);
});

test("mixed provisioners select exactly the branch, with dependents first", () => {
  const resources = [
    resource("network", { tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }),
    resource("boot", { stack_id: "stk-feat-a" }),
    resource("cdk-instance", { labels: { Branch: "feat-a" }, depends_on: ["network", "boot"] }),
    resource("cdk-volume", { labels: { BRANCH: "feat-a" } }),
    resource("cdk-snapshot", { labels: { branch: "feat-a" }, depends_on: ["cdk-volume"] }),
    resource("stack-anchor", { labels: { Branch: "feat-a" }, stack_id: "custom-stack" }),
    resource("stack-child", { stack_id: "custom-stack" }),
    resource("other", { labels: { Branch: "feat-b" } }),
    resource("other-in-stack", { labels: { Branch: "feat-b" }, stack_id: "stk-feat-a" }),
    resource("similar-stack", { stack_id: "stk-feat-a-v2" }),
    resource("feat-a-lookalike"),
  ];
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.blocked, []);
  const ids = plan.steps.map((r) => r.id);
  assert.deepEqual([...ids].sort(), [
    "network", "boot", "cdk-instance", "cdk-volume", "cdk-snapshot", "stack-anchor", "stack-child",
  ].sort());
  assert.ok(ids.indexOf("cdk-instance") < ids.indexOf("network"));
  assert.ok(ids.indexOf("cdk-instance") < ids.indexOf("boot"));
  assert.ok(ids.indexOf("cdk-snapshot") < ids.indexOf("cdk-volume"));
});

test("genuine external dependents still block teardown", () => {
  const plan = buildPlan([
    resource("network", { tags: { branch: "feat-a" } }),
    resource("external", { labels: { Branch: "feat-b" }, depends_on: ["network"] }),
  ], "feat-a");
  assert.deepEqual(plan.blocked, [{ id: "network", dependents: ["external"] }]);
});
EOF

