      const dependents = [...resources.values()].filter((r) => r.depends_on.includes(id));
      if (dependents.length) return reply(409, { error: "resource has dependents", dependents: dependents.map((r) => r.id) });
      if (!resources.delete(id)) return reply(404, { error: "not found" });
      deleted.push(id);
      return reply(200, { deleted: id });
    }
    reply(404, { error: "not found" });
