test("CLI retains labels across pages for plan, list, GC and teardown", async (t) => {
  const cloud = await mockCloud(t, [
    resource("network", { tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }),
    resource("boot", { stack_id: "stk-feat-a" }),
    resource("cdk-instance", { labels: { Branch: "feat-a" }, depends_on: ["network", "boot"] }),
    resource("cdk-volume", { labels: { BRANCH: "feat-a" } }),
    resource("cdk-snapshot", { labels: { bRaNcH: "feat-a" }, depends_on: ["cdk-volume"] }),
    resource("other", { labels: { Branch: "feat-b" } }),
    resource("similar-stack", { stack_id: "stk-feat-a-v2" }),
    resource("orphan"),
  ], true);
  const { stdout, stderr } = await cloud.run("plan", "--branch", "feat-a", "--json");
  assert.match(stderr, /rate limited/);
  const plan = JSON.parse(stdout);
  assert.deepEqual(plan.blocked, []);
  const ids = plan.steps.map((r: { id: string }) => r.id);
  assert.deepEqual([...ids].sort(), ["network", "boot", "cdk-instance", "cdk-volume", "cdk-snapshot"].sort());
  assert.deepEqual(cloud.cursors, ["0", "page /2?"]);
  assert.match((await cloud.run("list")).stdout, /feat-a\s+4/);
  assert.match((await cloud.run("list")).stdout, /feat-b\s+1/);
  assert.match((await cloud.run("gc", "--untagged")).stdout, /3 untagged resources/);
  await cloud.run("teardown", "--branch", "feat-a", "--dry-run");
  assert.deepEqual(cloud.deleted, []);
  assert.match((await cloud.run("teardown", "--branch", "feat-a")).stdout, /complete \(5 resources\)/);
  assert.deepEqual(cloud.deleted, ids);
  assert.deepEqual([...cloud.resources.keys()], ["other", "similar-stack", "orphan"]);
  assert.deepEqual(JSON.parse((await cloud.run("plan", "--branch", "feat-a", "--json")).stdout).steps, []);
});

test("CLI refuses teardown when a genuinely external branch still depends on it", async (t) => {
  const cloud = await mockCloud(t, [
    resource("network", { tags: { branch: "feat-a" } }),
    resource("external", { labels: { Branch: "feat-b" }, depends_on: ["network"] }),
  ]);
  const plan = JSON.parse((await cloud.run("plan", "--branch", "feat-a", "--json")).stdout);
  assert.deepEqual(plan.blocked, [{ id: "network", dependents: ["external"] }]);
  await assert.rejects(cloud.run("teardown", "--branch", "feat-a"), (err: Error & { code?: number; stderr?: string }) => {
    assert.equal(err.code, 1);
    assert.match(err.stderr!, /refusing to tear down/);
    return true;
  });
  assert.deepEqual(cloud.deleted, []);
  assert.equal(cloud.resources.size, 2);
});
